const puppeteer = require('puppeteer');
const fs = require('fs');

(async () => {
    let browser;
    try {
        browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
        const page = await browser.newPage();

        // Use a simple http server, or directly load the file url
        const fileUrl = 'file://' + __dirname + '/index.html';

        // Wait until network is idle since it's downloading React and Babel
        await page.goto(fileUrl, { waitUntil: 'networkidle0' });

        // Wait an extra bit to make sure babel compiled and react rendered
        await page.waitForSelector('#root .header', { timeout: 10000 });

        // Add Axe
        await page.addScriptTag({ path: require.resolve('axe-core') });

        const results = await page.evaluate(async () => {
            return await window.axe.run(document);
        });

        const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
        const bp = results.violations.filter(v => v.tags.includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        if (wcag.length > 0) {
            process.exit(1);
        }
    } catch (err) {
        console.error("Error:", err);
        process.exit(1);
    } finally {
        if (browser) await browser.close();
    }
})();

